1013			if remoteVolume, ok := remoteVolumeMap[vmiVolume.VolumeName]; ok {
1014				log.Log.V(5).Infof("Merging volume %s", vmiVolume.VolumeName)
1015				// Found a match merge the current target volume with the incoming source volume
1016				mergedVolume := virtv1.StorageMigratedVolumeInfo{
1017					VolumeName: vmiVolume.VolumeName,
1018				}
1019				if vmiVolume.SourcePVCInfo != nil {
1020					mergedVolume.SourcePVCInfo = vmiVolume.SourcePVCInfo.DeepCopy()
1021				} else {
1022					mergedVolume.SourcePVCInfo = remoteVolume.SourcePVCInfo.DeepCopy()
1023				}
1024				if vmiVolume.DestinationPVCInfo != nil {
1025					mergedVolume.DestinationPVCInfo = vmiVolume.DestinationPVCInfo.DeepCopy()
1026				}
1027				mergedVolumes = append(mergedVolumes, mergedVolume)
1028				delete(remoteVolumeMap, vmiVolume.VolumeName)
1029			}
1030		}
1031		for _, volume := range remoteVolumeMap {
1032			mergedVolumes = append(mergedVolumes, volume)
