41	func (p *PatchOperation) MarshalJSON() ([]byte, error) {
42		switch p.Op {
43		// The 'remove' operation is the only patching operation without a value
44		// and it needs to be parsed differently.
45		case PatchRemoveOp:
46			return json.Marshal(&struct {
47				Op   string `json:"op"`
48				Path string `json:"path"`
49			}{
50				Op:   p.Op,
51				Path: p.Path,
52			})
53		case PatchTestOp, PatchReplaceOp, PatchAddOp:
54			return json.Marshal(&struct {
55				Op    string      `json:"op"`
56				Path  string      `json:"path"`
57				Value interface{} `json:"value"`
58			}{
59				Op:    p.Op,
60				Path:  p.Path,
61				Value: p.Value,
62			})
63		default:
64			return nil, fmt.Errorf("operation %s not recognized", p.Op)
65		}
66	}
