198	func (c *MigrationTargetController) ackMigrationCompletion(vmi *v1.VirtualMachineInstance, domain *api.Domain) {
199		// as fallback set the target migration start timestamp
200		if vmi.Status.MigrationState.StartTimestamp == nil && domain.Spec.Metadata.KubeVirt.Migration.StartTimestamp != nil {
201			vmi.Status.MigrationState.StartTimestamp = domain.Spec.Metadata.KubeVirt.Migration.StartTimestamp
202		}
203		vmi.Status.MigrationState.EndTimestamp = domain.Spec.Metadata.KubeVirt.Migration.EndTimestamp
204		vmi.Labels[v1.NodeNameLabel] = c.host
205		if _, exists := vmi.GetAnnotations()[v1.EvictionSourceAnnotation]; exists {
206			delete(vmi.Annotations, v1.EvictionSourceAnnotation)
207		}
208		delete(vmi.Labels, v1.OutdatedLauncherImageLabel)
209		vmi.Status.LauncherContainerImageVersion = ""
210		vmi.Status.NodeName = c.host
211		// clean the evacuation node name since have already migrated to a new node
212		vmi.Status.EvacuationNodeName = ""
213		// update the vmi migrationTransport to indicate that the next migration should use unix URI
214		// new workloads will set the migrationTransport on creation, however legacy workloads
215		// can make the switch only after the first migration
216		vmi.Status.MigrationTransport = v1.MigrationTransportUnix
217		// Update the memory overhead to reflect the target pod's overhead after migration completes
218		if vmi.Status.MigrationState.TargetMemoryOverhead != nil {
219			if vmi.Status.Memory == nil {
220				vmi.Status.Memory = &v1.MemoryStatus{}
221			}
222			vmi.Status.Memory.MemoryOverhead = vmi.Status.MigrationState.TargetMemoryOverhead
223		}
224		c.recorder.Event(vmi, k8sv1.EventTypeNormal, v1.Migrated.String(), fmt.Sprintf("The VirtualMachineInstance migrated to node %s.", c.host))
225		c.logger.Object(vmi).Info("The target node detected that the migration has completed")
226	}
