228	func (c *MigrationTargetController) updateStatus(vmi *v1.VirtualMachineInstance, domain *api.Domain) error {
229		if migrations.MigrationFailed(vmi) {
230			c.logger.Object(vmi).V(4).Info("migration has failed, nothing to report on the target node")
231			return nil
232		}
233	
234		domainExists := domain != nil
235	
236		// detect domain on target node
237		if domainExists && !vmi.Status.MigrationState.TargetNodeDomainDetected {
238			// record that we've seen the domain populated on the target's node
239			c.logger.Object(vmi).Info("The target node received the migrated domain")
240			vmi.Status.MigrationState.TargetNodeDomainDetected = true
241			if vmi.Status.MigrationState.TargetState != nil {
242				vmi.Status.MigrationState.TargetState.DomainDetected = true
243			}
244	
245			// adjust QEMU process memlock limits in order to enable old virt-launcher pod's to
246			// perform host-devices hotplug post migration.
247			if err := c.hypervisorRuntime.AdjustResources(vmi, c.clusterConfig.GetConfig()); err != nil {
248				c.recorder.Event(vmi, k8sv1.EventTypeWarning, err.Error(), "Failed to update target node qemu memory limits during live migration")
249			}
250		}
251	
252		// detect an active domain on target node
253		if domainIsActiveOnTarget(domain) && vmi.Status.MigrationState.TargetNodeDomainReadyTimestamp == nil {
254			// record the moment we detected the domain is running.
255			// This is used as a trigger to help coordinate when CNI drivers
256			// fail over the IP to the new pod.
257			vmi.Status.MigrationState.TargetNodeDomainReadyTimestamp = pointer.P(metav1.Now())
258			if vmi.Status.MigrationState.TargetState != nil {
259				vmi.Status.MigrationState.TargetState.DomainReadyTimestamp = vmi.Status.MigrationState.TargetNodeDomainReadyTimestamp
260			}
261	
262			c.logger.Object(vmi).Info("The target node received the running migrated domain")
263	
264			cm := controller.NewVirtualMachineInstanceConditionManager()
265			cm.RemoveCondition(vmi, v1.VirtualMachineInstanceMigrationRequired)
266		}
267	
268		// migration is complete, ack it
269		if domainExists &&
270			domain.Spec.Metadata.KubeVirt.Migration != nil &&
271			domain.Spec.Metadata.KubeVirt.Migration.EndTimestamp != nil {
272			c.ackMigrationCompletion(vmi, domain)
273		}
274	
275		if migrations.IsMigrating(vmi) {
276			c.logger.Object(vmi).V(4).Info("migration is already in progress")
277			return nil
278		}
279	
280		vmiUID := string(vmi.UID)
281		if vmi.Status.MigrationState.SourceState != nil && vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID != nil {
282			vmiUID = string(*vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID)
283		}
284		destSrcPortsMap := c.migrationProxy.GetTargetListenerPorts(vmiUID)
285		if len(destSrcPortsMap) == 0 {
286			msg := "target migration listener is not up for this vmi, giving it time"
287			c.logger.Object(vmi).Info(msg)
288			c.queue.AddAfter(controller.VirtualMachineInstanceKey(vmi), time.Second*1)
289			return nil
290		}
291	
292		hostAddress := ""
293		// advertise target address
294		if vmi.Status.MigrationState != nil {
295			hostAddress = vmi.Status.MigrationState.TargetNodeAddress
296		}
297		if hostAddress != c.migrationIpAddress {
298			portsList := make([]string, 0, len(destSrcPortsMap))
299	
300			for k := range destSrcPortsMap {
301				portsList = append(portsList, k)
302			}
303			portsStrList := strings.Trim(strings.Join(strings.Fields(fmt.Sprint(portsList)), ","), "[]")
304			c.recorder.Event(vmi, k8sv1.EventTypeNormal, v1.PreparingTarget.String(), fmt.Sprintf("Migration Target is listening at %s, on ports: %s", c.migrationIpAddress, portsStrList))
305			vmi.Status.MigrationState.TargetNodeAddress = c.migrationIpAddress
306			vmi.Status.MigrationState.TargetDirectMigrationNodePorts = destSrcPortsMap
307			if vmi.Status.MigrationState.TargetState != nil {
308				vmi.Status.MigrationState.TargetState.NodeAddress = pointer.P(c.migrationIpAddress)
309				vmi.Status.MigrationState.TargetState.DirectMigrationNodePorts = destSrcPortsMap
310			}
311		}
312	
313		// If the migrated VMI requires dedicated CPUs, report the new pod CPU set to the source node
314		// via the VMI migration status in order to patch the domain pre migration
315		if vmi.IsCPUDedicated() {
316			err := c.reportDedicatedCPUSetForMigratingVMI(vmi)
317			if err != nil {
318				return err
319			}
320			err = c.reportTargetTopologyForMigratingVMI(vmi)
321			if err != nil {
322				return err
323			}
324		}
325	
326		return nil
327	}
