329	func (c *MigrationTargetController) Run(threadiness int, stopCh chan struct{}) {
330		defer c.queue.ShutDown()
331		c.logger.Info("Starting virt-handler target controller.")
332	
333		cache.WaitForCacheSync(stopCh, c.hasSynced)
334	
335		// queue keys for previous Domains on the host that no longer exist
336		// in the cache. This ensures we perform local cleanup of deleted VMs.
337		for _, domain := range c.domainStore.List() {
338			d := domain.(*api.Domain)
339			vmiRef := v1.NewVMIReferenceWithUUID(
340				d.ObjectMeta.Namespace,
341				d.ObjectMeta.Name,
342				d.Spec.Metadata.KubeVirt.UID)
343	
344			key := controller.VirtualMachineInstanceKey(vmiRef)
345	
346			_, exists, _ := c.vmiStore.GetByKey(key)
347			if !exists {
348				c.queue.Add(key)
349			}
350		}
351	
352		// Start the actual work
353		for i := 0; i < threadiness; i++ {
354			go wait.Until(c.runWorker, time.Second, stopCh)
355		}
356	
357		<-stopCh
358		c.logger.Info("Stopping virt-handler target controller.")
359	}
