366	func (c *MigrationTargetController) Execute() bool {
367		key, quit := c.queue.Get()
368		if quit {
369			return false
370		}
371		defer c.queue.Done(key)
372		if err := c.execute(key); err != nil {
373			c.logger.Reason(err).Infof("re-enqueuing VirtualMachineInstance %v", key)
374			c.queue.AddRateLimited(key)
375		} else {
376			c.logger.V(4).Infof("processed VirtualMachineInstance %v", key)
377			c.queue.Forget(key)
378		}
379		return true
380	}
