576	func (c *MigrationTargetController) handleTargetMigrationProxy(vmi *v1.VirtualMachineInstance) error {
577		// handle starting/stopping target migration proxy
578		var migrationTargetSockets []string
579		res, err := c.podIsolationDetector.Detect(vmi)
580		if err != nil {
581			return err
582		}
583		vmiUID := string(vmi.UID)
584		if vmi.Status.MigrationState.SourceState != nil && vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID != nil {
585			vmiUID = string(*vmi.Status.MigrationState.SourceState.VirtualMachineInstanceUID)
586		}
587	
588		// Get the libvirt connection socket file on the destination pod.
589		socketFile := fmt.Sprintf(filepath.Join(c.virtLauncherFSRunDirPattern, "libvirt/virtqemud-sock"), res.Pid())
590		// the migration-proxy is no longer shared via host mount, so we
591		// pass in the virt-launcher's baseDir to reach the unix sockets.
592		baseDir := fmt.Sprintf(filepath.Join(c.virtLauncherFSRunDirPattern, "kubevirt"), res.Pid())
593		migrationTargetSockets = append(migrationTargetSockets, socketFile)
594	
595		migrationPortsRange := migrationproxy.GetMigrationPortsList(vmi.IsBlockMigration())
596		for _, port := range migrationPortsRange {
597			key := migrationproxy.ConstructProxyKey(vmiUID, port)
598			// a proxy between the target direct qemu channel and the connector in the destination pod
599			destSocketFile := migrationproxy.SourceUnixFile(baseDir, key)
600			migrationTargetSockets = append(migrationTargetSockets, destSocketFile)
601		}
602		err = c.migrationProxy.StartTargetListener(vmiUID, migrationTargetSockets)
603		if err != nil {
604			return err
605		}
606		return nil
607	}
