609	func replaceMigratedVolumesStatus(vmi *v1.VirtualMachineInstance) {
610		replaceVolsStatus := make(map[string]*v1.PersistentVolumeClaimInfo)
611		for _, v := range vmi.Status.MigratedVolumes {
612			if v.SourcePVCInfo != nil {
613				replaceVolsStatus[v.SourcePVCInfo.ClaimName] = v.DestinationPVCInfo
