//     in a "test" operation (asserting the old value) followed by a "replace"
//     operation (setting the new value).
//   - Unchanged fields are skipped, producing no operations.
//
// If newMS is nil, the entire migrationState is being removed, so a "test"
// (asserting origMS) followed by a "remove" is emitted for "/status/migrationState".
func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	const basePath = "/status/migrationState"

	if newMS == nil {
		if origMS != nil {
			patchSet.AddOption(
				patch.WithTest(basePath, origMS),
				patch.WithRemove(basePath),
			)
		}
		return
	}

	if origMS == nil {
		origMS = &virtv1.VirtualMachineInstanceMigrationState{}
	}

	origValue := reflect.ValueOf(origMS).Elem()
	newValue := reflect.ValueOf(newMS).Elem()
	stateType := newValue.Type()

	for i := 0; i < stateType.NumField(); i++ {
		fieldName := jsonFieldName(stateType.Field(i))
		if fieldName == "" {
			continue
		}

		origField := origValue.Field(i)
		newField := newValue.Field(i)
		origZero := origField.IsZero()
		newZero := newField.IsZero()

		switch {
		case origZero && newZero:
			// Both zero, nothing changed.
			continue
		case origZero && !newZero:
			// Zero to non-zero, add the field.
			patchSet.AddOption(patch.WithAdd(basePath+"/"+fieldName, newField.Interface()))
		case !origZero && !newZero:
			// Non-zero to non-zero. Only patch if the value actually changed.
			if apiequality.Semantic.DeepEqual(origField.Interface(), newField.Interface()) {
				continue
			}
			patchSet.AddOption(
				patch.WithTest(basePath+"/"+fieldName, origField.Interface()),
				patch.WithReplace(basePath+"/"+fieldName, newField.Interface()),
			)
		}
	}
}

// jsonFieldName returns the JSON field name for the given struct field, or an
// empty string if the field is not serialized to JSON.
func jsonFieldName(field reflect.StructField) string {
	tag := field.Tag.Get("json")
	if tag == "" || tag == "-" {
		return ""
	}
	name := strings.Split(tag, ",")[0]
	if name == "" || name == "-" {
		return ""
	}
	return name
}

